import React, { useEffect, useState, useMemo } from 'react';
import api from '../services/api';
import ProfModal from './ProfModal';

const VILLES = ['Tunis','Sfax','Sousse','Monastir','Nabeul','Bizerte','Kairouan','Ariana','Ben Arous','Mahdia'];

function Stars({ n, size = '.88rem' }) {
  const v = parseFloat(n) || 0;
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 3 }}>
      {[1,2,3,4,5].map(i => (
        <span key={i} style={{ color: i <= Math.floor(v) ? '#f59e0b' : 'var(--border)', fontSize: size }}>★</span>
      ))}
      <span style={{ color: 'var(--text2)', fontSize: '.78rem', marginLeft: 3 }}>{v.toFixed(1)}</span>
    </span>
  );
}

function ModeBadge({ mode }) {
  const cfg = {
    en_ligne:   { icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.1)'  },
    presentiel: { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.1)'  },
    les_deux:   { icon: '🔀', label: 'Les deux',   color: '#6c63ff', bg: 'rgba(108,99,255,0.1)' },
  }[mode] || { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.1)' };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.68rem', fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      {cfg.icon} {cfg.label}
    </span>
  );
}

function getTarifMin(prof) {
  const tarifs = [prof.tarif_en_ligne, prof.tarif_presentiel]
    .filter(v => v !== null && v !== undefined && v !== '' && parseFloat(v) > 0)
    .map(Number);
  return tarifs.length ? Math.min(...tarifs) : null;
}

function ProfCard({ prof, onView }) {
  const [hovered, setHovered] = useState(false);
  const nom      = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';
  const matieres = prof.tarifs_matieres ? [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 3) : [];
  const tarifMin = getTarifMin(prof);

  return (
    <div
      onClick={() => onView(prof)}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{ background: 'var(--card)', border: hovered ? '1px solid rgba(108,99,255,0.5)' : '1px solid var(--border)', borderRadius: 20, overflow: 'hidden', cursor: 'pointer', transform: hovered ? 'translateY(-5px)' : 'none', boxShadow: hovered ? '0 20px 60px rgba(108,99,255,0.2)' : 'none', transition: 'all .3s cubic-bezier(.34,1.56,.64,1)' }}
    >
      <div style={{ height: 90, background: hovered ? 'linear-gradient(135deg,rgba(108,99,255,.5),rgba(255,101,132,.35))' : 'linear-gradient(135deg,rgba(108,99,255,.3),rgba(255,101,132,.2))', position: 'relative', transition: 'background .3s' }}>
        <div style={{ position: 'absolute', top: 10, right: 12 }}><ModeBadge mode={prof.mode_enseignement} /></div>
        <div style={{ width: 72, height: 72, borderRadius: '50%', border: '3px solid var(--card)', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.6rem', overflow: 'hidden', position: 'absolute', bottom: -36, left: 20, boxShadow: hovered ? '0 8px 24px rgba(108,99,255,0.4)' : '0 4px 12px rgba(0,0,0,0.3)', transition: 'box-shadow .3s' }}>
          {prof.photo_url ? <img src={'http://localhost:8001' + prof.photo_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
        </div>
      </div>

      <div style={{ padding: '44px 20px 20px' }}>
        <div style={{ marginBottom: 8 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.05rem', marginBottom: 3 }}>{nom}</div>
          {prof.ville && <div style={{ fontSize: '.78rem', color: 'var(--text2)' }}>📍 {prof.ville}</div>}
        </div>

        <div style={{ marginBottom: 12 }}>
          <Stars n={prof.note_moyenne} />
          <span style={{ fontSize: '.74rem', color: 'var(--text2)', marginLeft: 6 }}>{prof.nb_avis} avis</span>
        </div>

        {matieres.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, marginBottom: 12 }}>
            {matieres.map(m => <span key={m} style={{ fontSize: '.7rem', fontWeight: 600, padding: '3px 9px', borderRadius: 20, background: 'rgba(108,99,255,0.1)', color: '#6c63ff' }}>{m}</span>)}
            {prof.tarifs_matieres && prof.tarifs_matieres.length > 3 && <span style={{ fontSize: '.7rem', color: 'var(--text2)' }}>+{prof.tarifs_matieres.length - 3}</span>}
          </div>
        )}

        <div style={{ height: 1, background: 'var(--border)', margin: '12px 0' }} />

        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div>
            {tarifMin ? (
              <div>
                <span style={{ fontSize: '.7rem', color: 'var(--text2)' }}>À partir de </span>
                <span style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.1rem', color: '#43e97b' }}>{tarifMin}</span>
                <span style={{ fontSize: '.72rem', color: 'var(--text2)' }}> DT/h</span>
              </div>
            ) : (
              <span style={{ fontSize: '.78rem', color: 'var(--text2)', fontStyle: 'italic' }}>Tarif sur demande</span>
            )}
          </div>
          <button onClick={e => { e.stopPropagation(); onView(prof); }} style={{ padding: '8px 16px', background: hovered ? 'linear-gradient(135deg,#6c63ff,#8b5cf6)' : 'var(--surface2)', color: hovered ? '#fff' : 'var(--text)', border: hovered ? 'none' : '1px solid var(--border)', borderRadius: 10, fontWeight: 600, cursor: 'pointer', fontSize: '.8rem', transition: 'all .2s' }}>
            Voir profil →
          </button>
        </div>
      </div>
    </div>
  );
}

export default function Profs() {
  const [profs, setProfs]       = useState([]);
  const [loading, setLoading]   = useState(true);
  const [selectedProf, setSelectedProf] = useState(null);
  const [search, setSearch]     = useState('');
  const [filterVille, setFilterVille] = useState('');
  const [filterMode, setFilterMode]   = useState('');
  const [filterBudget, setFilterBudget] = useState('');
  const [sort, setSort]         = useState('note');
  const [viewMode, setViewMode] = useState('grid');
  const [matieres, setMatieres] = useState([]);
  const [filterMat, setFilterMat] = useState('');

  useEffect(() => {
    Promise.all([
      api.get('/api/professeurs/'),
      api.get('/api/admin/referentiel/structure'),
    ]).then(([rProfs, rStruct]) => {
      setProfs(rProfs.data);
      const allMats = [];
      rStruct.data.forEach(dom => dom.niveaux?.forEach(niv => niv.matieres?.forEach(m => allMats.push(m.nom))));
      setMatieres([...new Set(allMats)]);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []);

  const filtered = useMemo(() => {
    return profs.filter(p => {
      const nom  = `${p.user_prenom || ''} ${p.user_nom || ''}`.toLowerCase();
      const mats = p.tarifs_matieres?.map(t => t.nom_matiere.toLowerCase()) || [];
      if (search && !nom.includes(search.toLowerCase()) && !mats.some(m => m.includes(search.toLowerCase()))) return false;
      if (filterVille && p.ville !== filterVille) return false;
      if (filterMode  && p.mode_enseignement !== filterMode) return false;
      if (filterMat   && !mats.includes(filterMat.toLowerCase())) return false;
      if (filterBudget) {
        const min = getTarifMin(p);
        if (min !== null && min > Number(filterBudget)) return false;
      }
      return true;
    }).sort((a, b) => {
      if (sort === 'note')  return parseFloat(b.note_moyenne || 0) - parseFloat(a.note_moyenne || 0);
      if (sort === 'tarif') {
        const ta = getTarifMin(a) ?? Infinity;
        const tb = getTarifMin(b) ?? Infinity;
        return ta - tb;
      }
      if (sort === 'avis') return (b.nb_avis || 0) - (a.nb_avis || 0);
      return 0;
    });
  }, [profs, search, filterVille, filterMode, filterMat, filterBudget, sort]);

  const hasFilters = search || filterVille || filterMode || filterMat || filterBudget;
  const resetFilters = () => { setSearch(''); setFilterVille(''); setFilterMode(''); setFilterMat(''); setFilterBudget(''); setSort('note'); };

  const stats = useMemo(() => ({
    total:      profs.length,
    enligne:    profs.filter(p => p.mode_enseignement === 'en_ligne'   || p.mode_enseignement === 'les_deux').length,
    presentiel: profs.filter(p => p.mode_enseignement === 'presentiel' || p.mode_enseignement === 'les_deux').length,
    noteMoy:    profs.length ? (profs.reduce((s, p) => s + parseFloat(p.note_moyenne || 0), 0) / profs.length).toFixed(1) : '0',
  }), [profs]);

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.85rem', outline: 'none', width: '100%' };

  return (
    <div style={{ padding: 32, maxWidth: 1400, margin: '0 auto' }}>
      <div style={{ marginBottom: 28 }}>
        <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.6rem', marginBottom: 6 }}>👨‍🏫 Professeurs</div>
        <div style={{ color: 'var(--text2)', fontSize: '.88rem' }}>Trouvez le professeur idéal parmi nos experts vérifiés</div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 16, marginBottom: 28 }}>
        {[
          { icon: '👨‍🏫', val: stats.total,      lbl: 'Professeurs',      color: '#6c63ff', bg: 'rgba(108,99,255,.1)' },
          { icon: '🌐', val: stats.enligne,    lbl: 'Cours en ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,.1)'  },
          { icon: '🏫', val: stats.presentiel, lbl: 'Cours présentiel', color: '#43e97b', bg: 'rgba(67,233,123,.1)'  },
          { icon: '⭐', val: stats.noteMoy,    lbl: 'Note moyenne',     color: '#f59e0b', bg: 'rgba(245,158,11,.1)'  },
        ].map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 14 }}>
            <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem', flexShrink: 0 }}>{s.icon}</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.5rem', color: s.color, lineHeight: 1 }}>{s.val}</div>
              <div style={{ fontSize: '.75rem', color: 'var(--text2)', marginTop: 2 }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 20, marginBottom: 24 }}>
        <div style={{ display: 'flex', gap: 12, marginBottom: 14, alignItems: 'center' }}>
          <div style={{ position: 'relative', flex: 1 }}>
            <span style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)' }}>🔍</span>
            <input style={{ ...inp, paddingLeft: 36 }} placeholder="Rechercher par nom, matière..." value={search} onChange={e => setSearch(e.target.value)} />
          </div>
          <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 10, padding: 3, gap: 3 }}>
            {[['grid','⊞'],['list','☰']].map(([v, icon]) => (
              <button key={v} onClick={() => setViewMode(v)} style={{ width: 36, height: 36, borderRadius: 8, border: 'none', cursor: 'pointer', fontSize: '1rem', background: viewMode === v ? '#6c63ff' : 'transparent', color: viewMode === v ? '#fff' : 'var(--text2)' }}>{icon}</button>
            ))}
          </div>
          {hasFilters && <button onClick={resetFilters} style={{ padding: '9px 14px', background: 'rgba(255,101,132,0.1)', color: '#ff6584', border: '1px solid rgba(255,101,132,0.3)', borderRadius: 10, cursor: 'pointer', fontWeight: 600, fontSize: '.8rem', whiteSpace: 'nowrap' }}>✕ Réinitialiser</button>}
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5,1fr)', gap: 10 }}>
          <select style={inp} value={filterMat} onChange={e => setFilterMat(e.target.value)}>
            <option value="">📚 Toutes matières</option>
            {matieres.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
          <select style={inp} value={filterVille} onChange={e => setFilterVille(e.target.value)}>
            <option value="">📍 Toutes villes</option>
            {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
          </select>
          <select style={inp} value={filterMode} onChange={e => setFilterMode(e.target.value)}>
            <option value="">🎓 Tous modes</option>
            <option value="en_ligne">🌐 En ligne</option>
            <option value="presentiel">🏫 Présentiel</option>
            <option value="les_deux">🔀 Les deux</option>
          </select>
          <div style={{ position: 'relative' }}>
            <span style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', color: 'var(--text2)' }}>💰</span>
            <input type="number" min="0" style={{ ...inp, paddingLeft: 30 }} placeholder="Budget max (DT/h)" value={filterBudget} onChange={e => setFilterBudget(e.target.value)} />
          </div>
          <select style={inp} value={sort} onChange={e => setSort(e.target.value)}>
            <option value="note">⭐ Meilleure note</option>
            <option value="tarif">💸 Moins cher</option>
            <option value="avis">💬 Plus d'avis</option>
          </select>
        </div>
        {hasFilters && (
          <div style={{ display: 'flex', gap: 8, marginTop: 12, flexWrap: 'wrap' }}>
            {search      && <FilterTag label={`"${search}"`} onRemove={() => setSearch('')} />}
            {filterMat   && <FilterTag label={filterMat}     onRemove={() => setFilterMat('')} />}
            {filterVille && <FilterTag label={filterVille}   onRemove={() => setFilterVille('')} />}
            {filterMode  && <FilterTag label={filterMode.replace('_',' ')} onRemove={() => setFilterMode('')} />}
            {filterBudget && <FilterTag label={`≤ ${filterBudget} DT/h`} onRemove={() => setFilterBudget('')} />}
          </div>
        )}
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <div style={{ fontSize: '.88rem', color: 'var(--text2)' }}>
          <span style={{ fontWeight: 700, color: 'var(--text)' }}>{filtered.length}</span> professeur{filtered.length !== 1 ? 's' : ''} trouvé{filtered.length !== 1 ? 's' : ''}
          {hasFilters && <span style={{ color: '#6c63ff' }}> · Filtres actifs</span>}
        </div>
      </div>

      {loading ? (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 20 }}>
          {[1,2,3,4,5,6].map(i => <SkeletonCard key={i} />)}
        </div>
      ) : filtered.length === 0 ? (
        <EmptyState hasFilters={hasFilters} onReset={resetFilters} />
      ) : viewMode === 'grid' ? (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 20 }}>
          {filtered.map(p => <ProfCard key={p.id} prof={p} onView={setSelectedProf} />)}
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {filtered.map(p => <ProfListItem key={p.id} prof={p} onView={setSelectedProf} />)}
        </div>
      )}

      {selectedProf && <ProfModal prof={selectedProf} onClose={() => setSelectedProf(null)} />}
    </div>
  );
}

function FilterTag({ label, onRemove }) {
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: '.75rem', fontWeight: 600, padding: '3px 10px', borderRadius: 20, background: 'rgba(108,99,255,0.12)', color: '#6c63ff', border: '1px solid rgba(108,99,255,0.25)' }}>
      {label}<span onClick={onRemove} style={{ cursor: 'pointer', fontWeight: 800 }}>✕</span>
    </span>
  );
}

function ProfListItem({ prof, onView }) {
  const nom      = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';
  const matieres = prof.tarifs_matieres ? [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 4) : [];
  const tarifMin = getTarifMin(prof);
  return (
    <div onClick={() => onView(prof)} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 16, cursor: 'pointer', transition: 'all .2s' }}
      onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(108,99,255,0.4)'; }}
      onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; }}>
      <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.4rem', overflow: 'hidden', flexShrink: 0 }}>
        {prof.photo_url ? <img src={'http://localhost:8001' + prof.photo_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : '👨‍🏫'}
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '.95rem', marginBottom: 3 }}>{nom}</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
          {prof.ville && <span style={{ fontSize: '.75rem', color: 'var(--text2)' }}>📍 {prof.ville}</span>}
          <Stars n={prof.note_moyenne} size=".75rem" />
          <span style={{ fontSize: '.73rem', color: 'var(--text2)' }}>{prof.nb_avis} avis</span>
        </div>
      </div>
      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', maxWidth: 250 }}>
        {matieres.map(m => <span key={m} style={{ fontSize: '.68rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20, background: 'rgba(108,99,255,0.1)', color: '#6c63ff' }}>{m}</span>)}
      </div>
      <div style={{ textAlign: 'right', flexShrink: 0 }}>
        <ModeBadge mode={prof.mode_enseignement} />
        {tarifMin
          ? <div style={{ marginTop: 4 }}><span style={{ fontFamily: 'Syne', fontWeight: 800, color: '#43e97b', fontSize: '1rem' }}>{tarifMin}</span><span style={{ fontSize: '.72rem', color: 'var(--text2)' }}> DT/h</span></div>
          : <div style={{ marginTop: 4, fontSize: '.72rem', color: 'var(--text2)', fontStyle: 'italic' }}>Sur demande</div>}
      </div>
      <button onClick={e => { e.stopPropagation(); onView(prof); }} style={{ padding: '8px 14px', background: 'var(--surface2)', color: 'var(--text)', border: '1px solid var(--border)', borderRadius: 9, fontWeight: 600, cursor: 'pointer', fontSize: '.8rem', flexShrink: 0 }}>Voir →</button>
    </div>
  );
}

function SkeletonCard() {
  return (
    <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, overflow: 'hidden' }}>
      <div style={{ height: 90, background: 'var(--surface2)', animation: 'pulse 1.5s infinite' }} />
      <div style={{ padding: '44px 20px 20px' }}>
        {[['70%','1rem'],['40%','.7rem'],['90%','.7rem'],['60%','.7rem']].map(([w, h], i) => (
          <div key={i} style={{ height: h, background: 'var(--surface2)', borderRadius: 6, marginBottom: 10, width: w, animation: 'pulse 1.5s infinite' }} />
        ))}
      </div>
      <style>{`@keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}`}</style>
    </div>
  );
}

function EmptyState({ hasFilters, onReset }) {
  return (
    <div style={{ textAlign: 'center', padding: '80px 20px', background: 'var(--card)', borderRadius: 20, border: '1px solid var(--border)' }}>
      <div style={{ fontSize: '3rem', marginBottom: 16 }}>{hasFilters ? '🔍' : '👨‍🏫'}</div>
      <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '1.1rem', marginBottom: 8 }}>{hasFilters ? 'Aucun résultat' : 'Aucun professeur disponible'}</div>
      <div style={{ color: 'var(--text2)', fontSize: '.88rem', marginBottom: 20 }}>{hasFilters ? 'Essayez de modifier vos filtres.' : 'Revenez bientôt !'}</div>
      {hasFilters && <button onClick={onReset} style={{ padding: '10px 24px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 600, cursor: 'pointer' }}>Réinitialiser les filtres</button>}
    </div>
  );
}
